async function hydrateDocuments(typeCode='BOL'){try{const [documents,receipts]=await Promise.all([apiRequest(`/documents?type=${encodeURIComponent(typeCode)}&limit=100`),typeCode==='BOL'?apiRequest('/receipts?limit=100').catch(()=>({items:[]})):{items:[]}]);const items=[...documents.items,...receipts.items].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,100);fillListRows(items.map(item=>{const folio=item.number?`${item.prefix||''}/${String(item.number).padStart(6,'0')}`:`Borrador #${item.id}`;const status=statusLabels[item.status]||item.status;const actions=item.source==='receipt'?'<small>Histórica</small>':item.status==='draft'?`<button type="button" class="secondary-button compact-action" data-resume-sale="${item.id}">Continuar</button>`:`<button type="button" class="secondary-button compact-action" data-print-sale="${item.id}">Imprimir</button>${Number(item.pending_total)>0&&item.status!=='cancelled'?`<button type="button" class="secondary-button compact-action" data-later-payment="${item.id}" data-pending="${item.pending_total}">Abonar</button>`:''}`;return `<tr><td><input type="checkbox" aria-label="Seleccionar registro" /></td><td>${escapeHtml(folio)}</td><td>${escapeHtml(item.branch||'Casa matriz')}</td><td>${escapeHtml(item.customer_name||'Venta directa')}</td><td><span class="status ${statusClass(status)}">${escapeHtml(status)}</span></td><td>${clp(item.paid_total)}</td><td>${clp(item.pending_total)}</td><td>${clp(item.discount_total)}</td><td>${clp(item.total)}</td><td>${shortDate(item.created_at,false)}</td><td class="sale-list-actions">${actions}</td></tr>`}).join(''),items.length)}catch(error){notify('No se pudieron cargar los documentos: '+error.message)}}
