function ensureProductLookup(){let lookup=document.querySelector('[data-product-lookup]');if(!lookup){lookup=document.createElement('div');lookup.className='product-lookup';lookup.dataset.productLookup='';lookup.id='product-search-results';lookup.hidden=true;document.body.appendChild(lookup)}return lookup}
function positionProductLookup(){const input=activeProductSearchInput,lookup=document.querySelector('[data-product-lookup]');if(!input||!lookup||lookup.hidden)return;const rect=input.getBoundingClientRect(),width=Math.min(690,window.innerWidth-24),left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12));let top=rect.bottom+2,space=window.innerHeight-top-10;if(space<170&&rect.top>200){space=rect.top-12;top=Math.max(12,rect.top-Math.min(350,space))}lookup.style.left=left+'px';lookup.style.top=top+'px';lookup.style.width=width+'px';lookup.style.maxHeight=Math.max(130,Math.min(350,space))+'px'}
