async function searchTicketProducts(input){activeProductSearchInput=input;const lookup=ensureProductLookup();input.setAttribute('aria-expanded','true');lookup.innerHTML='<div class="product-lookup-status">Buscando artículos…</div>';lookup.hidden=false;positionProductLookup();try{const query=input.value.trim();const result=await apiRequest('/products?limit=20&q='+encodeURIComponent(query));if(activeProductSearchInput!==input)return;const rows=result.items.map(item=>'<button type="button" role="option" class="product-lookup-row" data-product-result data-id="'+escapeHtml(item.id)+'" data-name="'+escapeHtml(item.name)+'" data-description="'+escapeHtml(item.description||item.name)+'" data-sku="'+escapeHtml(item.sku)+'" data-price="'+Number(item.price_amount||0)+'" data-stock="'+Number(item.stock_quantity||0)+'"><span>—</span><span>'+escapeHtml(item.sku)+'</span><span>'+escapeHtml(item.description||item.name)+'</span><span>'+Number(item.price_amount||0).toLocaleString('es-CL')+'</span><span>'+Number(item.stock_quantity||0).toLocaleString('es-CL')+'</span></button>').join('');lookup.innerHTML='<div class="product-lookup-head"><span>Ref.</span><span>Cod. Barras</span><span>Descripción</span><span>PVP</span><span>Stock</span></div>'+(rows||'<div class="product-lookup-status">No se encontraron productos con esa búsqueda.</div>');positionProductLookup()}catch(error){if(activeProductSearchInput===input){lookup.innerHTML='<div class="product-lookup-status">No se pudo buscar en el catálogo. Comprueba la conexión con la base.</div>';positionProductLookup()}}}
