document.addEventListener('keydown',event=>{if(!activeProductSearchInput)return;if(event.key==='Escape'){hideProductLookup();return}const lookup=document.querySelector('[data-product-lookup]');if(!lookup||lookup.hidden)return;const current=event.target.closest('[data-product-result]'),options=[...lookup.querySelectorAll('[data-product-result]')];if(event.key==='ArrowDown'){event.preventDefault();if(!current)options[0]?.focus();else options[Math.min(options.indexOf(current)+1,options.length-1)]?.focus()}else if(event.key==='ArrowUp'&&current){event.preventDefault();if(options.indexOf(current)<=0)activeProductSearchInput.focus();else options[options.indexOf(current)-1]?.focus()}else if(event.key==='Enter'&&current){event.preventDefault();current.click()}});
